-- REB commercial vacancy statistics, source periods 2024 Q3 to 2026 Q2.
-- Prerequisite: TypeORM migration 0000000000008-create-reb-vacancy-schema.ts.
-- Geometry source: REB R-ONE commercial statistical-map WFS.
-- The data remains in REB survey geography and must not be copied into
-- commercial_area_feature as if it were a direct measurement of that area.

BEGIN;

DO $prerequisite$
BEGIN
  IF to_regclass('public.reb_vacancy_import') IS NULL
     OR to_regclass('public.reb_statistical_area') IS NULL
     OR to_regclass('public.reb_vacancy_reporting_area') IS NULL
     OR to_regclass('public.reb_vacancy_observation') IS NULL THEN
    RAISE EXCEPTION 'REB vacancy schema is missing. Run TypeORM migrations first.';
  END IF;
END;
$prerequisite$;

