INSERT INTO public.reb_vacancy_reporting_area (
  import_id,
  statistical_area_id,
  source_area_key,
  source_region_code,
  asset_type,
  area_level,
  level1_name,
  level2_name,
  area_name,
  boundary_year,
  created_at,
  updated_at
)
SELECT
  import_row.id,
  statistical_area.id,
  source_rows.source_area_key,
  source_rows.source_region_code,
  source_rows.asset_type,
  source_rows.area_level,
  source_rows.level1_name,
  source_rows.level2_name,
  source_rows.area_name,
  2024,
  now(),
  now()
FROM source_rows
JOIN public.reb_vacancy_import AS import_row
  ON import_row.dataset_code = 'REB_VACANCY_2024_BOUNDARY_2026Q2'
LEFT JOIN public.reb_statistical_area AS statistical_area
  ON statistical_area.source_gid = source_rows.source_gid
 AND statistical_area.boundary_year = 2024
ON CONFLICT (source_area_key, boundary_year) DO UPDATE
SET import_id = EXCLUDED.import_id,
    statistical_area_id = EXCLUDED.statistical_area_id,
    source_region_code = EXCLUDED.source_region_code,
    asset_type = EXCLUDED.asset_type,
    area_level = EXCLUDED.area_level,
    level1_name = EXCLUDED.level1_name,
    level2_name = EXCLUDED.level2_name,
    area_name = EXCLUDED.area_name,
    updated_at = now();

