INSERT INTO public.reb_vacancy_observation (
  reporting_area_id,
  import_id,
  base_period,
  vacancy_rate_pct,
  created_at,
  updated_at
)
SELECT
  reporting_area.id,
  import_row.id,
  source_values.base_period,
  source_values.vacancy_rate_pct::numeric(5, 2),
  now(),
  now()
FROM source_values
JOIN public.reb_vacancy_reporting_area AS reporting_area
  ON reporting_area.source_area_key = source_values.source_area_key
 AND reporting_area.boundary_year = 2024
JOIN public.reb_vacancy_import AS import_row
  ON import_row.dataset_code = 'REB_VACANCY_2024_BOUNDARY_2026Q2'
ON CONFLICT (reporting_area_id, base_period) DO UPDATE
SET import_id = EXCLUDED.import_id,
    vacancy_rate_pct = EXCLUDED.vacancy_rate_pct,
    updated_at = now();

DO $validation$
DECLARE
  reporting_area_count BIGINT;
  local_market_count BIGINT;
  geometry_count BIGINT;
  observation_count BIGINT;
  invalid_geometry_count BIGINT;
  invalid_rate_count BIGINT;
BEGIN
  SELECT count(*)
    INTO reporting_area_count
    FROM public.reb_vacancy_reporting_area AS reporting_area
    JOIN public.reb_vacancy_import AS import_row
      ON import_row.id = reporting_area.import_id
   WHERE import_row.dataset_code = 'REB_VACANCY_2024_BOUNDARY_2026Q2';

  SELECT count(*)
    INTO local_market_count
    FROM public.reb_vacancy_reporting_area AS reporting_area
    JOIN public.reb_vacancy_import AS import_row
      ON import_row.id = reporting_area.import_id
   WHERE import_row.dataset_code = 'REB_VACANCY_2024_BOUNDARY_2026Q2'
     AND reporting_area.area_level = 'LOCAL_MARKET'
     AND reporting_area.statistical_area_id IS NOT NULL;

  SELECT count(DISTINCT reporting_area.statistical_area_id)
    INTO geometry_count
    FROM public.reb_vacancy_reporting_area AS reporting_area
    JOIN public.reb_vacancy_import AS import_row
      ON import_row.id = reporting_area.import_id
   WHERE import_row.dataset_code = 'REB_VACANCY_2024_BOUNDARY_2026Q2'
     AND reporting_area.area_level = 'LOCAL_MARKET';

  SELECT count(*)
    INTO observation_count
    FROM public.reb_vacancy_observation AS observation
    JOIN public.reb_vacancy_import AS import_row
      ON import_row.id = observation.import_id
   WHERE import_row.dataset_code = 'REB_VACANCY_2024_BOUNDARY_2026Q2';

  SELECT count(*)
    INTO invalid_geometry_count
    FROM public.reb_statistical_area AS statistical_area
   WHERE statistical_area.boundary_year = 2024
     AND (
       ST_IsEmpty(statistical_area.geom)
       OR ST_SRID(statistical_area.geom) <> 5186
       OR NOT ST_IsValid(statistical_area.geom)
     );

  SELECT count(*)
    INTO invalid_rate_count
    FROM public.reb_vacancy_observation AS observation
    JOIN public.reb_vacancy_import AS import_row
      ON import_row.id = observation.import_id
   WHERE import_row.dataset_code = 'REB_VACANCY_2024_BOUNDARY_2026Q2'
     AND (observation.vacancy_rate_pct < 0 OR observation.vacancy_rate_pct > 100);

  IF reporting_area_count <> 173
     OR local_market_count <> 156
     OR geometry_count <> 69
     OR observation_count <> 1384
     OR invalid_geometry_count <> 0
     OR invalid_rate_count <> 0 THEN
    RAISE EXCEPTION
      'REB vacancy import validation failed (reporting %, local %, geometry %, observation %, invalid geometry %, invalid rate %).',
      reporting_area_count,
      local_market_count,
      geometry_count,
      observation_count,
      invalid_geometry_count,
      invalid_rate_count;
  END IF;

  RAISE NOTICE 'REB vacancy import validated: 69 polygons, 173 reporting areas, 1,384 observations.';
END;
$validation$;

COMMIT;
